            BridgeCallContext? context = null)
        {
            if (request == null)
            {
                throw new ArgumentNullException(nameof(request));
            }

            var ct = context?.Token ?? default;
            if (ct.IsCancellationRequested)
            {
                return new AppleStoreKitServiceFinishTransactionResult.Failure(
                    new HiveError(HiveErrorCode.Cancelled, "Operation was cancelled."));
            }

            if (!HiveCore.TryResolve<INativeBridge>(out var bridge) || bridge == null)
            {
                return new AppleStoreKitServiceFinishTransactionResult.Failure(
                    new HiveError(HiveErrorCode.FailedPrecondition, "HiveCore is not initialized; the native bridge is unavailable."));
            }

            try
            {
                var writer = new JsonWriter();
                request.WriteTo(writer);
                string payload = writer.ToJsonString();
#if UNITY_WEBGL
                // Resume on the caller's context (required on single-threaded WebGL;
                // ConfigureAwait(false) here queues to a ThreadPool that never runs).
                string response = await bridge.CallAsync(PluginName, "FinishTransaction", payload, ct);
#else
                string response = await bridge.CallAsync(PluginName, "FinishTransaction", payload, ct).ConfigureAwait(false);
#endif
                return ParseFinishTransactionEnvelope(response);
            }
            catch (Exception ex) when (ex is OperationCanceledException || ex is ObjectDisposedException)
            {
                // Mid-call cancellation, or a bridge disposed during shutdown,
                // surfaces as a Cancelled result — matching the entry-point check
                // above — instead of throwing out of this method.
                return new AppleStoreKitServiceFinishTransactionResult.Failure(
                    new HiveError(HiveErrorCode.Cancelled, "Operation was cancelled."));
            }
        }

        private static AppleStoreKitServiceFinishTransactionResult ParseFinishTransactionEnvelope(string json)
        {
            try
            {
                return ParseFinishTransactionEnvelopeCore(json);
            }
            catch (Exception)
            {
                // A malformed native payload (wrong token type, truncated JSON,
                // invalid base64, ...) must surface as a Failure rather than let
                // an exception escape the bridge call.
                return new AppleStoreKitServiceFinishTransactionResult.Failure(
                    new HiveError(HiveErrorCode.Internal, "Malformed bridge response envelope."),
                    json);
            }
        }

        private static AppleStoreKitServiceFinishTransactionResult ParseFinishTransactionEnvelopeCore(string json)
        {
            var r = new JsonReader(json);
            r.Read();
            while (r.Read() && r.TokenType != JsonTokenType.EndObject)
            {
                if (r.TokenEquals("success"))
                {
                    r.Read();
                    return new AppleStoreKitServiceFinishTransactionResult.Success(FinishTransactionResponse.FromJson(r), json);
                }
                else if (r.TokenEquals("error"))
                {
                    r.Read();
                    return new AppleStoreKitServiceFinishTransactionResult.Failure(HiveBridgeErrorEnvelope.ReadError(r), json);
                }
                else if (r.TokenEquals("outcome"))
                {
                    r.Read();
                    string code = string.Empty;
                    while (r.Read() && r.TokenType != JsonTokenType.EndObject)
                    {
                        if (r.TokenEquals("code")) { r.Read(); if (r.TokenType != JsonTokenType.Null) { code = r.ReadString(); } }
                        else { r.Read(); r.Skip(); }
                    }
                    switch (code)
                    {
                        case "transaction_not_found":
                            return new AppleStoreKitServiceFinishTransactionResult.TransactionNotFound(json);
                        default:
                            return new AppleStoreKitServiceFinishTransactionResult.UnknownOutcome(code, json);
                    }
                }
                else
                {
                    r.Read();
                    r.Skip();
                }
            }

            return new AppleStoreKitServiceFinishTransactionResult.Failure(
                new HiveError(HiveErrorCode.Internal, "Malformed bridge response envelope."),
                json);
        }

